import{_ as t,o as n,c as a,a2 as i}from"./chunks/framework.e4u2V5E7.js";const h=JSON.parse('{"title":"Ddd","description":"Ddd reference documentation","frontmatter":{"title":"Ddd","description":"Ddd reference documentation"},"headers":[],"relativePath":"knowledge/ddd.md","filePath":"knowledge/ddd.md","lastUpdated":1784485118000}'),s={name:"knowledge/ddd.md"};function o(r,e,l,d,g,c){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="ddd" tabindex="-1">Ddd <a class="header-anchor" href="#ddd" aria-label="Permalink to &quot;Ddd&quot;">​</a></h1><h1 id="domain-driven-design-—-knowledge-base" tabindex="-1">Domain-Driven Design — Knowledge Base <a class="header-anchor" href="#domain-driven-design-—-knowledge-base" aria-label="Permalink to &quot;Domain-Driven Design — Knowledge Base&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Domain-Driven Design (DDD) is an approach to software development that centers the implementation on a model of the core business domain. It bridges the gap between technical implementation and business requirements through collaborative modeling and strategic design patterns.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="strategic-design" tabindex="-1">Strategic Design <a class="header-anchor" href="#strategic-design" aria-label="Permalink to &quot;Strategic Design&quot;">​</a></h3><p><strong>Bounded Contexts</strong> A bounded context defines a boundary within which a particular domain model applies. Different contexts may use the same terms with different meanings (e.g., &quot;Product&quot; in Sales vs Inventory).</p><p><strong>Ubiquitous Language</strong> A shared language between developers and domain experts that is used consistently in code, documentation, and conversation. Every term maps directly to code artifacts.</p><p><strong>Context Mapping</strong> Defines relationships between bounded contexts:</p><ul><li><strong>Shared Kernel</strong> — Two contexts share a common model</li><li><strong>Customer-Supplier</strong> — Upstream context provides; downstream context consumes</li><li><strong>Anti-Corruption Layer (ACL)</strong> — Translates between incompatible models</li><li><strong>Open Host Service</strong> — One context exposes a public API for others</li><li><strong>Published Language</strong> — Standard format for cross-context communication</li></ul><h3 id="tactical-design" tabindex="-1">Tactical Design <a class="header-anchor" href="#tactical-design" aria-label="Permalink to &quot;Tactical Design&quot;">​</a></h3><p><strong>Entities</strong> Objects defined by their identity, not their attributes. Two entities with different data but the same ID are the same entity.</p><p><strong>Value Objects</strong> Immutable objects defined by their attributes, not identity. <code>Money(100, &#39;USD&#39;)</code> equals <code>Money(100, &#39;USD&#39;)</code> regardless of which instance.</p><p><strong>Aggregates</strong> Clusters of entities and value objects treated as a single unit for data changes. The aggregate root is the only entry point for modifications.</p><p><strong>Repositories</strong> Abstract the data access layer for aggregates. Each aggregate type has one repository that handles persistence.</p><p><strong>Domain Services</strong> Operations that don&#39;t naturally belong to any entity or value object. They encapsulate domain logic that spans multiple aggregates.</p><p><strong>Domain Events</strong> Records of something meaningful happening in the domain. <code>OrderPlaced</code>, <code>PaymentReceived</code>, <code>InventoryDepleted</code>.</p><p><strong>Factories</strong> Encapsulate complex object creation logic, especially when constructing aggregates with many invariants.</p><h3 id="aggregate-design-rules" tabindex="-1">Aggregate Design Rules <a class="header-anchor" href="#aggregate-design-rules" aria-label="Permalink to &quot;Aggregate Design Rules&quot;">​</a></h3><ol><li>Protect business invariants within aggregate boundaries</li><li>Design small aggregates — reference other aggregates by identity, not by direct object reference</li><li>One transaction modifies one aggregate only</li><li>Use eventual consistency between aggregates</li><li>The aggregate root is the only entry point for state changes</li></ol><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Start with domain modeling</strong> — Before writing code, map the domain with stakeholders; identify bounded contexts and ubiquitous language</li><li><strong>Keep aggregates small</strong> — Small aggregates reduce contention and improve performance; reference other aggregates by ID</li><li><strong>Use value objects liberally</strong> — Replace primitive types with meaningful value objects (<code>Email</code>, <code>Money</code>, <code>Address</code>); they enforce invariants</li><li><strong>Implement domain events for decoupling</strong> — When a state change affects other contexts, emit a domain event; let subscribers react independently</li><li><strong>Use the anti-corruption layer for external systems</strong> — Never let external API models leak into your domain; translate at the boundary</li><li><strong>Persist aggregates through repositories</strong> — Repositories abstract persistence; domain code never calls database directly</li><li><strong>Write domain logic in entities and services, not use cases</strong> — Use cases orchestrate; entities enforce invariants; services handle cross-aggregate logic</li><li><strong>Refactor toward deeper insight</strong> — DDD is iterative; as understanding grows, refactor the model to reflect new insights</li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><strong>Anemic domain model</strong> — Entities with only getters/setters and all logic in services; business rules belong in entities</li><li><strong>God aggregate</strong> — An aggregate containing too many entities creates contention; split into smaller, focused aggregates</li><li><strong>Direct database access in domain code</strong> — Domain entities calling Supabase or Prisma directly breaks the abstraction; use repositories</li><li><strong>Leaking infrastructure into domain</strong> — Importing HTTP libraries, database clients, or UI frameworks in domain code couples it to infrastructure</li><li><strong>Ignoring bounded contexts</strong> — Applying a single model across the entire application creates confusion; context boundaries separate concerns</li><li><strong>Over-engineering simple domains</strong> — Not every application needs full DDD; apply tactics proportionally to domain complexity</li><li><strong>Using ORM models as domain entities</strong> — Database models should not be domain entities; map between them at repository boundaries</li><li><strong>Missing ubiquitous language</strong> — Using technical jargon instead of domain terms creates misalignment between code and business understanding</li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><strong>Modeling database tables as aggregates</strong> — Database structure differs from domain structure; design aggregates based on business invariants, not tables</li><li><strong>Creating aggregates without clear invariants</strong> — An aggregate should protect at least one invariant; if it doesn&#39;t, it may not need to be an aggregate</li><li><strong>Using value objects for everything</strong> — Some things genuinely have identity (users, orders); forcing value object semantics causes problems</li><li><strong>Ignoring event sourcing implications</strong> — Domain events are not audit logs; they represent facts that trigger reactions, not just records</li><li><strong>Over-relying on domain services</strong> — If a domain service has no state and just coordinates entities, it may belong in the use case layer</li><li><strong>Not updating the model</strong> — DDD is iterative; as understanding deepens, the model should evolve; stale models cause misalignment</li><li><strong>Applying DDD to all layers</strong> — DDD is most valuable in the domain layer; UI and infrastructure benefit from other patterns</li><li><strong>Forgetting that aggregates enforce invariants synchronously</strong> — If an invariant requires cross-aggregate checks, use eventual consistency</li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Domain Complexity</th><th>Recommendation</th></tr></thead><tbody><tr><td>Simple CRUD (blog, portfolio)</td><td>MVC pattern; DDD overhead is unnecessary</td></tr><tr><td>Moderate business logic (e-commerce)</td><td>Tactical DDD: value objects, repositories, domain events</td></tr><tr><td>Complex domain (fintech, healthcare)</td><td>Full DDD: bounded contexts, aggregates, ubiquitous language</td></tr><tr><td>Multiple teams</td><td>Strategic DDD: context mapping, bounded contexts per team</td></tr><tr><td>Legacy modernization</td><td>Strangler fig pattern with DDD bounded contexts</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>&quot;Domain-Driven Design&quot; by Eric Evans (the blue book)</li><li>&quot;Implementing Domain-Driven Design&quot; by Vaughn Vernon</li><li>&quot;Domain-Driven Design Distilled&quot; by Vaughn Vernon</li><li>Martin Fowler&#39;s DDD resources: <a href="https://martinfowler.com/tags/domain%20driven%20design.html" target="_blank" rel="noreferrer">https://martinfowler.com/tags/domain driven design.html</a></li><li>ddd-crew resources: <a href="https://github.com/ddd-crew" target="_blank" rel="noreferrer">https://github.com/ddd-crew</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li><strong>TypeScript value objects:</strong> Use readonly classes or branded types for value objects with validation in constructors</li><li><strong>Supabase repositories:</strong> Implement repository interfaces with Supabase client; map between database rows and domain entities</li><li><strong>Domain events in Next.js:</strong> Use event emitters for in-process events; use message queues (Supabase Edge Functions) for async cross-context events</li><li><strong>Aggregates and RLS:</strong> Aggregate boundaries can map to RLS policies; the aggregate root&#39;s ID becomes the access control anchor</li><li><strong>Modeling sessions:</strong> Schedule domain modeling sessions with stakeholders quarterly; the model should evolve with business understanding</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>',34)])])}const m=t(s,[["render",o]]);export{h as __pageData,m as default};
